style.css:
@-moz-document domain("skroutz.gr") {
/*
  @name skroutz.gr dark
  @namespace svg url(http://www.w3.org/2000/svg);
  @version 1.0.0
*/
body,
.filters-list,
.tags-group,
header.site-header,
#skus_show header.site-header,
.sku-details,
h2.section-title {
    background-color: #0a0a0a;
    color: white;
}
* {
    color: white !important;
}
.content-scrollable:before {
    background: -webkit-linear-gradient(left, #0a0a0a, rgba(241, 241, 241, 0));
    background: linear-gradient(to right, #0a0a0a, rgba(241, 241, 241, 0));
}
.content-scrollable:after {
    background: -webkit-linear-gradient(right, #0a0a0a, rgba(241, 241, 241, 0));
    background: linear-gradient(to left, #0a0a0a, rgba(241, 241, 241, 0));
}
.header-user-actions > li.sign-in a,
.header-user-actions > li > a,
.bc h1 a,
.bc h2 a,
.bc h3 a,
.bc h4 a,
.bc h5 a,
.bc nav > :last-child > a {
    color: white;
}
.guide-intro-button:hover,
.guide-intro-button.open,
.qna-intro-button:hover,
.qna-intro-button.open,
.switch-entrypoint-intro-button:hover,
.switch-entrypoint-intro-button.open,
.guide-intro-button,
.qna-intro-button,
.switch-entrypoint-intro-button,
.btn,
[class*="btn"],
.card,
.category-pills li a,
#search-bar-input,
#storefront-search-input,
.closable-tag,
[id^="suggestions_container"] .clean-button > span,
[id^="suggestions_container"],
.sku-info-bar,
.navigation-bar-wrapper .navigation-bar,
.user-review-images-container {
    background-color: #1a1a1a;
    color: white;
    border: none !important;
}
.tags-group {
    margin-top: 0;
}
.category-pills li a {
    padding: 5px;
    height: fit-content;
}
[class*="btn"]:hover,
#order-options li:hover,
.sort-options li:hover,
.closable-tag:hover,
[id^="suggestions_container"] .clean-button:hover > span,
[id^="suggestions_container"] .selected,
#popular a:hover {
    background-color: #2a2a2a !important;
    color: white;
}
.closable-tag:after {
    border: none;
    color: #fff;
}
.closable-tag {
    border-radius: 20px;
}
.pricedrop {
    background-color: #2a0a0c;
}
.main-content .card.category-discussion-prompt .answer p:before,
.review-item.expandable .review-body:after {
    background: -webkit-linear-gradient(transparent 16px, #1a1a1a);
    background: linear-gradient(transparent 16px, #1a1a1a);
}
.search-bar-input-wrapper.has-mega-menu .mega-menu-btn:hover {
    border-radius: 0 50px 50px 0;
}
[id^="suggestions_container"].active {
    margin-top: 10px;
    border-radius: 10px;
}
.offers-info p,
.offers-info p span {
    color: black !important;
}
.add-to-cart-wrap,
.add-to-cart-wrap .offerings-wrap,
.add-to-cart-wrap .offerings-wrap > div.selected,
.add-to-cart-wrap .offerings-wrap > div.selected .offering-card {
    background-color: #1a1a1a;
    color: white;
}
.add-to-cart-wrap {
    padding: 10px;
    border-radius: 10px;
}
.add-to-cart-wrap .offerings-wrap > div.selected {
    border: none;
}
.add-to-cart-wrap .select-location-wrapper,
.add-to-cart-wrap .add-to-cart-promos > div:not(.hidden) ~ div p {
    margin: 15px;
}
.sku-details {
    border-top: none;
    border-bottom: none;
}
.sku-info-bar.js-sku-info-bar.is-visible ~ .navigation-bar-wrapper .navigation-bar.remain-sticky {
    background-color: #1a1a1a;
    background-color: #1a1a1a;
    -webkit-transform: translateY(88px) !important;
    transform: translateY(88px) !important;
}
.navigation-bar-wrapper .navigation-bar.remain-sticky {
    box-shadow: 0 1px 4px 0 #0a0a0a;
}
.navigation-bar-wrapper .navigation-bar {
    background-color: #0a0a0a;
}
.navigation-bar .active-item-underline {
    background-color: #fff;
}
}
